USE new_aom_db;

INSERT IGNORE INTO cms_content (content_type, slug, locale, title, payload_json, status, sort_order) VALUES
('homepage', 'hero', 'en', 'Discover the Wisdom Within', JSON_OBJECT('eyebrow', 'Spirituality, Wisdom, Meditation & Cultural Harmony', 'body', 'Meditation, AUM Chanting, Yoga, Personal Development, Cultural Heritage, and Community Services.', 'button_label', 'Explore Our Services', 'button_url', '/services'), 'published', 0),
('about', 'about', 'en', 'A quieter mind. A kinder world.', JSON_OBJECT('body', 'NEW AOM fosters Spirituality and Wisdom, Meditation and AUM Chanting, Happiness and Personal Development, Yoga and Wellness, Cultural Heritage, Community Services, and Educational Knowledge Sharing.', 'vision', 'Peaceful, conscious, and compassionate living across global communities.', 'mission', 'Accessible meditation, AUM chanting, yoga, and cultural wisdom in five languages.', 'values', 'Authenticity, stillness, cultural respect, and selfless community service.'), 'published', 0),

('services', 'meditation-aum', 'en', 'Meditation and AUM Chanting', JSON_OBJECT('shortDesc', 'Guided breath awareness, inner stillness, and sacred AUM vibration practices.', 'fullDesc', 'Structured meditation and AUM chanting sessions designed to calm the nervous system, deepen focus, and awaken inner clarity for beginners and experienced practitioners alike.', 'duration', '60 Minutes', 'mode', 'In-Person & Online', 'icon', 'bi-soundwave'), 'published', 0),
('services', 'yoga-wellness', 'en', 'Yoga and Wellness', JSON_OBJECT('shortDesc', 'Holistic postures, pranayama breathing, and balanced daily living.', 'fullDesc', 'Gentle to intermediate yoga practices integrating physical alignment, breath regulation, and mindful relaxation to restore energy and flexibility.', 'duration', '75 Minutes', 'mode', 'Group & Private Sessions', 'icon', 'bi-heart-pulse'), 'published', 1),
('services', 'spiritual-guidance', 'en', 'Spiritual Guidance', JSON_OBJECT('shortDesc', 'Thoughtful mentorship on purpose, inner peace, and mindful living.', 'fullDesc', 'One-on-one and small group spiritual guidance focused on self-inquiry, emotional balance, and applying timeless wisdom to modern life.', 'duration', '45 Minutes', 'mode', 'Private Consultation', 'icon', 'bi-compass'), 'published', 2),
('services', 'personal-development', 'en', 'Personal Development', JSON_OBJECT('shortDesc', 'Clarity, resilience, positive habits, and emotional intelligence.', 'fullDesc', 'Practical personal development coaching that strengthens self-discipline, communication, and joyful goal setting rooted in inner awareness.', 'duration', '60 Minutes', 'mode', 'Workshop & 1-on-1', 'icon', 'bi-graph-up-arrow'), 'published', 3),
('services', 'original-sangeetham', 'en', 'Original Sangeetham', JSON_OBJECT('shortDesc', 'Meditative musical compositions and traditional vocal harmony.', 'fullDesc', 'Soulful Original Sangeetham sessions exploring devotional ragas, sound resonance, and musical expressions that elevate peace and concentration.', 'duration', '60 Minutes', 'mode', 'Live & Guided Sessions', 'icon', 'bi-music-note-beamed'), 'published', 4),
('services', 'healing-modalities', 'en', 'Healing Modalities', JSON_OBJECT('shortDesc', 'Natural energy balance, relaxation therapy, and holistic restoration.', 'fullDesc', 'Non-invasive holistic healing modalities supporting stress relief, emotional release, and mind-body harmony.', 'duration', '60 Minutes', 'mode', 'By Appointment', 'icon', 'bi-flower1'), 'published', 5),
('services', 'workshops-learning', 'en', 'Workshops and Learning Programmes', JSON_OBJECT('shortDesc', 'Interactive educational courses on wisdom, heritage, and wellness.', 'fullDesc', 'Multi-session workshops and community learning programmes covering meditation, Tamil cultural heritage, and holistic wellbeing.', 'duration', 'Half-Day / Multi-Week', 'mode', 'Community & Online', 'icon', 'bi-journal-bookmark'), 'published', 6),

('knowledge', 'morning-aum-practice', 'en', 'The Science and Stillness of Morning AUM Chanting', JSON_OBJECT('category', 'Spiritual Wisdom', 'date', '2026-10-12', 'summary', 'How ten minutes of conscious AUM resonance harmonizes breath, mind, and daily focus.', 'content', 'Chanting AUM with slow, steady exhalation creates a natural vibration across the chest and head, quieting mental chatter. Practicing early in the morning establishes emotional steadiness throughout the day.'), 'published', 0),
('knowledge', 'calm-living-habits', 'en', 'Five Simple Habits for Calm Living in a Busy World', JSON_OBJECT('category', 'Calm Living', 'date', '2026-10-20', 'summary', 'Practical daily pauses that restore mental clarity without disrupting your schedule.', 'content', 'Calm living begins with intentional transitions: mindful breathing before starting work, device-free meals, evening gratitude reflection, and restful sleep routines.'), 'published', 1),
('knowledge', 'love-and-happiness', 'en', 'Cultivating Unconditional Kindness and Everyday Joy', JSON_OBJECT('category', 'Love and Happiness', 'date', '2026-10-28', 'summary', 'Understanding happiness as an inner practice rather than an external condition.', 'content', 'When we shift attention from constant comparison to conscious appreciation, relationships deepen and everyday moments become sources of genuine contentment.'), 'published', 2),
('knowledge', 'tamil-siddha-wisdom', 'en', 'Foundations of Tamil Siddha Wellness & Natural Balance', JSON_OBJECT('category', 'Tamil Siddha Maruththuva Kalaihal', 'date', '2026-11-04', 'summary', 'Exploring traditional Tamil insights on seasonal nutrition, breath, and preventive living.', 'content', 'Tamil Siddha traditions emphasize harmony between food, breath, thought, and nature. Simple herbal infusions, mindful eating, and breathing discipline form the pillars of preventive wellness.'), 'published', 3),
('knowledge', 'mindful-motivation', 'en', 'Ethical Leadership and Mindful Motivation', JSON_OBJECT('category', 'Marketing, Meditation and Motivation', 'date', '2026-11-09', 'summary', 'Combining meditative clarity with purposeful action in professional and community work.', 'content', 'True motivation emerges when work aligns with service and integrity. Regular meditation sharpens decision-making and sustains calm leadership under pressure.'), 'published', 4),
('knowledge', 'fun-wellness-tips', 'en', 'Three-Minute Desk Reset: Breath, Posture, and Smile', JSON_OBJECT('category', 'Fun Tips', 'date', '2026-11-14', 'summary', 'A quick, refreshing reset you can practice anywhere in under three minutes.', 'content', 'Roll your shoulders back, take six slow abdominal breaths, relax your jaw, and notice the immediate shift in energy and mood.'), 'published', 5),

('spiritual-wisdom', 'spiritual-wisdom', 'en', 'Spiritual Wisdom', JSON_OBJECT('summary', 'Spiritual wisdom invites us to look beyond surface distractions and recognize the quiet awareness present within every breath. Through self-reflection, compassion, and disciplined practice, inner peace becomes a lived reality.'), 'published', 0),
('events', 'full-moon-aum-gathering', 'en', 'Full Moon Meditation & AUM Chanting Gathering', JSON_OBJECT('date', '2026-12-05', 'time', '06:00 PM – 08:00 PM', 'location', 'NEW AOM Wellness Hall & Live Stream', 'description', 'An evening of collective AUM chanting, guided silent meditation, and peaceful reflection.', 'bookingUrl', '/booking'), 'published', 0),
