('faq', 'participation', 'en', 'Who can participate in NEW AOM sessions and workshops?', JSON_OBJECT('question', 'Who can participate in NEW AOM sessions and workshops?', 'answer', 'Anyone seeking spiritual reflection, meditation, AUM chanting, yoga, or cultural learning is welcome, regardless of prior experience.'), 'published', 0),
('faq', 'donation-process', 'en', 'How do donations work on NEW AOM?', JSON_OBJECT('question', 'How do donations work on NEW AOM?', 'answer', 'Select a project, verify your email with a one-time OTP, and use the displayed bank transfer details or QR code directly.'), 'published', 1),
('faq', 'languages', 'en', 'Are sessions available in multiple languages?', JSON_OBJECT('question', 'Are sessions available in multiple languages?', 'answer', 'Yes, the website supports English, Tamil, French, Chinese (Simplified), and Swiss German.'), 'published', 2),

('ads', 'full-moon-feature', 'en', 'Full Moon Meditation & AUM Chanting Gathering', JSON_OBJECT('eyebrow', 'UPCOMING GATHERING', 'body', '2026-12-05 • 06:00 PM – 08:00 PM • NEW AOM Wellness Hall & Live Stream', 'linkUrl', '/events/full-moon-aum-gathering', 'position', 'top'), 'published', 0),
('homepage', 'hero', 'ta', 'உள்ளார்ந்த அமைதியையும் காலத்தால் அழியாத ஞானத்தையும் உணருங்கள்', JSON_OBJECT('eyebrow', 'ஆன்மீகம், ஞானம், தியானம் மற்றும் பண்பாட்டு நல்லிணக்கம்', 'body', 'தியானம், ஓம் மந்திர உச்சாடனம், யோகா, ஆளுமை வளர்ச்சி, பண்பாட்டு மரபு மற்றும் சமூக நலப் பணிகள்.', 'button_label', 'எங்கள் சேவைகளைக் காண்க', 'button_url', '/services'), 'published', 0),
('homepage', 'hero', 'fr', 'Éveillez le calme intérieur et la sagesse éternelle', JSON_OBJECT('eyebrow', 'Spiritualité, sagesse, méditation et harmonie culturelle', 'body', 'Méditation, chant AUM, yoga, développement personnel, héritage culturel et services communautaires.', 'button_label', 'Découvrir nos services', 'button_url', '/services'), 'published', 0),
('homepage', 'hero', 'zh', '唤醒内在宁静与永恒智慧', JSON_OBJECT('eyebrow', '灵性、智慧、冥想与文化和谐', 'body', '冥想、AUM 唱诵、瑜伽、个人成长、文化传承与社区服务。', 'button_label', '浏览我们的服务', 'button_url', '/services'), 'published', 0),
('homepage', 'hero', 'de-CH', 'Innere Ruhe und zeitlose Weisheit entdecken', JSON_OBJECT('eyebrow', 'Spiritualität, Weisheit, Meditation und kulturelle Harmonie', 'body', 'Meditation, AUM-Gesang, Yoga, persönliche Entwicklung, Kulturerbe und Gemeinschaftsdienste.', 'button_label', 'Unsere Angebote ansehen', 'button_url', '/services'), 'published', 0),
('about', 'about', 'ta', 'ஞானம், நல்வாழ்வு மற்றும் பண்பாட்டு நல்லிணக்கம்', JSON_OBJECT('body', 'NEW AOM ஆன்மீகம் மற்றும் ஞானம், தியானம் மற்றும் ஓம் மந்திர உச்சாடனம், மகிழ்ச்சி மற்றும் ஆளுமை வளர்ச்சி, யோகா மற்றும் நல்வாழ்வு, பண்பாட்டு மரபு, சமூக சேவை மற்றும் கல்விசார் அறிவுப் பகிர்வை ஊக்குவிக்கிறது.', 'vision', 'காலத்தால் அழியாத ஞானம் மற்றும் முழுமையான நல்வாழ்வு வழியாக உலகெங்கும் அமைதியான, விழிப்புணர்வான, கருணைமிக்க வாழ்க்கையை ஊக்குவித்தல்.', 'mission', 'ஐந்து மொழிகளில் தியானம், ஓம் உச்சாடனம், யோகா, பண்பாட்டுக் கல்வி மற்றும் சமூக ஆதரவை எளிதில் அணுகக்கூடியதாக வழங்குதல்.', 'values', 'கருணை, உண்மைத்தன்மை, உள்ளார்ந்த அமைதி, பண்பாட்டு மரியாதை மற்றும் தன்னலமற்ற சமூக சேவை.'), 'published', 0),
('about', 'about', 'fr', 'Sagesse, bien-être et harmonie culturelle', JSON_OBJECT('body', 'NEW AOM cultive la spiritualité et la sagesse, la méditation et le chant AUM, le bonheur et le développement personnel, le yoga et le bien-être, le patrimoine culturel, les services communautaires et le partage des connaissances.', 'vision', 'Inspirer une vie paisible, consciente et bienveillante dans les communautés du monde entier grâce à la sagesse et au bien-être holistique.', 'mission', 'Rendre accessibles la méditation, le chant AUM, le yoga, l’apprentissage culturel et les programmes communautaires en cinq langues.', 'values', 'Compassion, authenticité, calme intérieur, respect culturel et service communautaire désintéressé.'), 'published', 0),
('about', 'about', 'zh', '智慧、健康与文化和谐', JSON_OBJECT('body', 'NEW AOM 致力于灵性与智慧、冥想与 AUM 唱诵、幸福与个人成长、瑜伽与健康、文化传承、社区服务及教育知识分享。', 'vision', '通过恒久的智慧与整体健康，促进全球社区和平、觉知与慈悲的生活。', 'mission', '以五种语言提供便捷的冥想、AUM 唱诵、瑜伽、文化学习与社区支持项目。', 'values', '慈悲、真诚、内在宁静、尊重文化与无私的社区服务。'), 'published', 0),
('about', 'about', 'de-CH', 'Weisheit, Wohlbefinden und kulturelle Harmonie', JSON_OBJECT('body', 'NEW AOM fördert Spiritualität und Weisheit, Meditation und AUM-Gesang, Glück und persönliche Entwicklung, Yoga und Wohlbefinden, Kulturerbe, Gemeinschaftsdienste und den Austausch von Wissen.', 'vision', 'Mit zeitloser Weisheit und ganzheitlichem Wohlbefinden ein friedliches, bewusstes und mitfühlendes Leben in Gemeinschaften weltweit fördern.', 'mission', 'Meditation, AUM-Gesang, Yoga, kulturelles Lernen und Gemeinschaftsangebote in fünf Sprachen zugänglich machen.', 'values', 'Mitgefühl, Authentizität, innere Ruhe, kultureller Respekt und selbstloser Gemeinschaftsdienst.'), 'published', 0),

