('knowledge', 'morning-aum-practice', 'ta', 'காலை ஓம் உச்சாடனத்தின் அறிவியலும் அமைதியும்', JSON_OBJECT('category', 'ஆன்மீக ஞானம்', 'summary', 'பத்து நிமிட விழிப்புணர்வான ஓம் ஒலி, மூச்சு, மனம் மற்றும் அன்றாடக் கவனத்தை எவ்வாறு ஒருங்கிணைக்கிறது.', 'content', 'மெதுவான, சீரான மூச்சு வெளியேற்றத்துடன் ஓம் உச்சாடனம் செய்வது மார்பு மற்றும் தலைப்பகுதியில் இயல்பான அதிர்வை உருவாக்கி மனச் சலசலப்பைத் தணிக்க உதவும். காலையில் பயிற்சி செய்வது நாள் முழுவதும் உணர்ச்சி நிலைத்தன்மையை வளர்க்கும்.'), 'published', 0),
('knowledge', 'calm-living-habits', 'ta', 'அவசரமான வாழ்க்கையில் அமைதிக்கான ஐந்து எளிய பழக்கங்கள்', JSON_OBJECT('category', 'அமைதியான வாழ்க்கை', 'summary', 'உங்கள் அன்றாட அட்டவணையைப் பாதிக்காமல் மனத் தெளிவை மீட்டெடுக்கும் சிறிய இடைவேளைகள்.', 'content', 'வேலை தொடங்கும் முன் விழிப்புணர்வுடன் மூச்செடுத்தல், உணவின்போது சாதனங்களை விலக்கி வைத்தல், மாலையில் நன்றியுணர்வை நினைவுகூர்தல், சீரான உறக்கப் பழக்கம் ஆகியவை அமைதியான வாழ்வை உருவாக்கும்.'), 'published', 1),
('knowledge', 'love-and-happiness', 'ta', 'நிபந்தனையற்ற அன்பும் அன்றாட மகிழ்ச்சியும்', JSON_OBJECT('category', 'அன்பும் மகிழ்ச்சியும்', 'summary', 'மகிழ்ச்சியை வெளிப்புறச் சூழ்நிலையாக அல்ல, உள்ளார்ந்த பயிற்சியாகப் புரிந்துகொள்வோம்.', 'content', 'தொடர்ந்த ஒப்பீட்டிலிருந்து விழிப்புணர்வான நன்றியுணர்வுக்கு கவனத்தை மாற்றும்போது உறவுகள் ஆழமடைகின்றன; அன்றாடச் சிறு தருணங்களும் உண்மையான மனநிறைவின் ஆதாரமாகின்றன.'), 'published', 2),
('knowledge', 'tamil-siddha-wisdom', 'ta', 'தமிழ் சித்த நல்வாழ்வும் இயற்கைச் சமநிலையும்', JSON_OBJECT('category', 'தமிழ் சித்த மருத்துவக் கலைகள்', 'summary', 'பருவகால உணவு, மூச்சு மற்றும் நோய் தடுப்பு வாழ்வு குறித்த தமிழ் மரபு அறிவைப் பார்ப்போம்.', 'content', 'தமிழ் சித்த மரபு உணவு, மூச்சு, சிந்தனை மற்றும் இயற்கையின் ஒற்றுமையை வலியுறுத்துகிறது. எளிய மூலிகைப் பானங்கள், கவனமுடன் உண்பது, ஒழுங்கான மூச்சுப் பயிற்சி ஆகியவை முன்னெச்சரிக்கை நல்வாழ்வின் அடித்தளங்கள்.'), 'published', 3),
('knowledge', 'mindful-motivation', 'ta', 'நெறிமுறைத் தலைமைத்துவமும் விழிப்புணர்வான ஊக்கமும்', JSON_OBJECT('category', 'சந்தைப்படுத்தல், தியானம் மற்றும் ஊக்கம்', 'summary', 'தொழில் மற்றும் சமூகப் பணியில் தியானத் தெளிவையும் நோக்கமுள்ள செயலையும் இணைத்தல்.', 'content', 'சேவையும் நேர்மையும் இணைந்த பணியிலிருந்து உண்மையான ஊக்கம் உருவாகிறது. வழக்கமான தியானம் முடிவெடுக்கும் திறனைத் தெளிவாக்கி, அழுத்தமான சூழல்களிலும் அமைதியான தலைமைத்துவத்தைத் தக்கவைக்க உதவுகிறது.'), 'published', 4),
('knowledge', 'fun-wellness-tips', 'ta', 'மூன்று நிமிட மேசை இடைவேளை: மூச்சு, உடல்நிலை, புன்னகை', JSON_OBJECT('category', 'எளிய நல்வாழ்வு குறிப்புகள்', 'summary', 'எங்கும் மூன்று நிமிடங்களுக்குள் செய்யக்கூடிய புத்துணர்ச்சியூட்டும் பயிற்சி.', 'content', 'தோள்களைப் பின்னால் தளர்த்தி, வயிற்றை இயக்கி ஆறு முறை மெதுவாக மூச்செடுக்கவும். தாடையைத் தளர்த்தி, உங்கள் ஆற்றலும் மனநிலையும் மாறுவதை கவனியுங்கள்.'), 'published', 5),
('knowledge', 'morning-aum-practice', 'fr', 'La science et le calme du chant AUM matinal', JSON_OBJECT('category', 'Sagesse spirituelle', 'summary', 'Dix minutes de résonance AUM consciente harmonisent la respiration, l’esprit et la concentration quotidienne.', 'content', 'Chanter AUM en expirant lentement et régulièrement crée une vibration naturelle dans la poitrine et la tête, et apaise le flot des pensées. Une pratique matinale favorise la stabilité émotionnelle tout au long de la journée.'), 'published', 0),
('knowledge', 'calm-living-habits', 'fr', 'Cinq habitudes simples pour vivre sereinement dans un monde pressé', JSON_OBJECT('category', 'Vie sereine', 'summary', 'De courtes pauses quotidiennes qui clarifient l’esprit sans bouleverser votre emploi du temps.', 'content', 'La sérénité commence par des transitions conscientes : respirer avant le travail, manger sans écran, prendre un moment de gratitude le soir et préserver un sommeil réparateur.'), 'published', 1),
('knowledge', 'love-and-happiness', 'fr', 'Cultiver la bienveillance inconditionnelle et la joie au quotidien', JSON_OBJECT('category', 'Amour et bonheur', 'summary', 'Comprendre le bonheur comme une pratique intérieure plutôt qu’une condition extérieure.', 'content', 'En remplaçant la comparaison constante par une appréciation consciente, les relations s’approfondissent et les moments ordinaires deviennent de véritables sources de contentement.'), 'published', 2),
('knowledge', 'tamil-siddha-wisdom', 'fr', 'Les bases du bien-être Siddha tamoul et de l’équilibre naturel', JSON_OBJECT('category', 'Arts médicinaux Siddha tamouls', 'summary', 'Découvrir les savoirs tamouls sur l’alimentation saisonnière, la respiration et la prévention.', 'content', 'Les traditions Siddha tamoules soulignent l’harmonie entre alimentation, respiration, pensée et nature. Infusions simples, repas attentifs et discipline respiratoire sont les piliers d’un bien-être préventif.'), 'published', 3),
('knowledge', 'mindful-motivation', 'fr', 'Leadership éthique et motivation en pleine conscience', JSON_OBJECT('category', 'Marketing, méditation et motivation', 'summary', 'Allier clarté méditative et action porteuse de sens dans le travail et la vie communautaire.', 'content', 'La motivation authentique naît d’un travail guidé par le service et l’intégrité. La méditation régulière affine les décisions et soutient un leadership serein sous pression.'), 'published', 4),
('knowledge', 'fun-wellness-tips', 'fr', 'Pause au bureau en trois minutes : respiration, posture et sourire', JSON_OBJECT('category', 'Conseils pratiques', 'summary', 'Une pause vivifiante à pratiquer partout en moins de trois minutes.', 'content', 'Ramenez doucement les épaules en arrière, prenez six respirations abdominales lentes, relâchez la mâchoire et observez l’effet sur votre énergie et votre humeur.'), 'published', 5),
('knowledge', 'morning-aum-practice', 'zh', '清晨 AUM 唱诵的科学与宁静', JSON_OBJECT('category', '灵性智慧', 'summary', '每天十分钟有意识地唱诵 AUM，让呼吸、心境与日常专注更加协调。', 'content', '以缓慢、平稳的呼气唱诵 AUM，会在胸腔与头部产生自然振动，有助于平息纷杂思绪。清晨练习能帮助我们在一天中保持情绪稳定。'), 'published', 0),
('knowledge', 'calm-living-habits', 'zh', '忙碌生活中的五个宁静小习惯', JSON_OBJECT('category', '平静生活', 'summary', '不打乱日程的日常短暂停歇，也能恢复清晰的思绪。', 'content', '宁静生活始于有意识的转换：工作前专注呼吸、用餐时放下设备、晚间回想值得感恩之事，并保持良好的睡眠习惯。'), 'published', 1),
('knowledge', 'love-and-happiness', 'zh', '培养无条件的善意与日常喜悦', JSON_OBJECT('category', '爱与幸福', 'summary', '把幸福理解为一种内在练习，而非外在条件。', 'content', '当我们不再不断比较，而是有意识地欣赏当下，关系会更加深厚，平凡的日常也会成为真切满足的来源。'), 'published', 2),
('knowledge', 'tamil-siddha-wisdom', 'zh', '泰米尔悉达养生与自然平衡基础', JSON_OBJECT('category', '泰米尔悉达医学艺术', 'summary', '探索泰米尔传统中关于时令饮食、呼吸与预防保健的智慧。', 'content', '泰米尔悉达传统强调饮食、呼吸、思想与自然之间的和谐。简单的草本饮品、专注饮食与规律呼吸，是预防性健康的重要基础。'), 'published', 3),
('knowledge', 'mindful-motivation', 'zh', '正念激励与合乎伦理的领导力', JSON_OBJECT('category', '营销、冥想与激励', 'summary', '在职业与社区工作中，将冥想带来的清晰与有目标的行动结合起来。', 'content', '当工作与服务精神和诚信相结合，真正的动力便会产生。定期冥想有助于提升决策能力，并在压力下保持平和的领导力。'), 'published', 4),
('knowledge', 'fun-wellness-tips', 'zh', '三分钟办公桌放松：呼吸、姿势与微笑', JSON_OBJECT('category', '实用健康小贴士', 'summary', '随时随地都能进行的清新练习，不到三分钟即可完成。', 'content', '轻轻向后转动肩膀，缓慢进行六次腹式呼吸，放松下颌，并留意精力与情绪的变化。'), 'published', 5),
('knowledge', 'morning-aum-practice', 'de-CH', 'Wissenschaft und Stille des morgendlichen AUM-Gesangs', JSON_OBJECT('category', 'Spirituelle Weisheit', 'summary', 'Zehn Minuten bewusster AUM-Klang bringen Atem, Geist und tägliche Konzentration in Einklang.', 'content', 'Langsames, gleichmässiges Ausatmen beim AUM-Gesang erzeugt eine natürliche Schwingung in Brust und Kopf und beruhigt den Gedankenfluss. Eine morgendliche Praxis unterstützt emotionale Ausgeglichenheit während des Tages.'), 'published', 0),
('knowledge', 'calm-living-habits', 'de-CH', 'Fünf einfache Gewohnheiten für mehr Ruhe im Alltag', JSON_OBJECT('category', 'Gelassen leben', 'summary', 'Kurze tägliche Pausen schaffen Klarheit, ohne den Tagesplan durcheinanderzubringen.', 'content', 'Ein gelassener Alltag beginnt mit bewussten Übergängen: vor der Arbeit ruhig atmen, Mahlzeiten ohne Geräte geniessen, abends Dankbarkeit üben und für erholsamen Schlaf sorgen.'), 'published', 1),
('knowledge', 'love-and-happiness', 'de-CH', 'Bedingungslose Freundlichkeit und tägliche Freude pflegen', JSON_OBJECT('category', 'Liebe und Glück', 'summary', 'Glück als innere Übung verstehen und nicht als äussere Voraussetzung.', 'content', 'Wenn wir ständige Vergleiche durch bewusstes Wertschätzen ersetzen, vertiefen sich Beziehungen und alltägliche Augenblicke werden zu Quellen echter Zufriedenheit.'), 'published', 2),
('knowledge', 'tamil-siddha-wisdom', 'de-CH', 'Grundlagen tamilischer Siddha-Gesundheit und natürlicher Balance', JSON_OBJECT('category', 'Tamilische Siddha-Heilkunst', 'summary', 'Einblicke in tamilisches Wissen zu saisonaler Ernährung, Atmung und Gesundheitsvorsorge.', 'content', 'Die tamilische Siddha-Tradition betont das Zusammenspiel von Nahrung, Atem, Gedanken und Natur. Einfache Kräuteraufgüsse, achtsames Essen und eine bewusste Atmung bilden die Grundlage vorsorglicher Gesundheit.'), 'published', 3),
('knowledge', 'mindful-motivation', 'de-CH', 'Ethische Führung und achtsame Motivation', JSON_OBJECT('category', 'Marketing, Meditation und Motivation', 'summary', 'Meditative Klarheit mit zielgerichtetem Handeln im Beruf und in der Gemeinschaft verbinden.', 'content', 'Echte Motivation entsteht, wenn Arbeit von Dienst am Gemeinwohl und Integrität getragen wird. Regelmässige Meditation schärft Entscheidungen und unterstützt eine ruhige Führung unter Druck.'), 'published', 4),
('knowledge', 'fun-wellness-tips', 'de-CH', 'Drei Minuten am Schreibtisch: Atmung, Haltung und Lächeln', JSON_OBJECT('category', 'Praktische Tipps', 'summary', 'Eine erfrischende Übung, die überall in weniger als drei Minuten gelingt.', 'content', 'Rollen Sie die Schultern sanft nach hinten, nehmen Sie sechs langsame Bauchatemzüge, entspannen Sie den Kiefer und achten Sie auf die Veränderung von Energie und Stimmung.'), 'published', 5),

('spiritual-wisdom', 'spiritual-wisdom', 'ta', 'ஆன்மீக ஞானம்', JSON_OBJECT('summary', 'மேலோட்டமான கவனச்சிதறல்களைத் தாண்டி, ஒவ்வொரு மூச்சிலும் இருக்கும் அமைதியான விழிப்புணர்வைக் காண ஆன்மீக ஞானம் அழைக்கிறது. சுயபரிசீலனை, கருணை மற்றும் ஒழுங்கான பயிற்சியால் உள்ளார்ந்த அமைதி வாழ்வின் ஒரு பகுதியாகிறது.'), 'published', 0),
('spiritual-wisdom', 'spiritual-wisdom', 'fr', 'Sagesse spirituelle', JSON_OBJECT('summary', 'La sagesse spirituelle invite à dépasser les distractions superficielles et à reconnaître la présence silencieuse au cœur de chaque souffle. Par l’introspection, la compassion et une pratique régulière, la paix intérieure prend vie.'), 'published', 0),
('spiritual-wisdom', 'spiritual-wisdom', 'zh', '灵性智慧', JSON_OBJECT('summary', '灵性智慧引导我们超越表面的纷扰，觉察每一次呼吸中宁静的觉知。通过自我观照、慈悲与持续练习，内心的平和便能融入日常生活。'), 'published', 0),
('spiritual-wisdom', 'spiritual-wisdom', 'de-CH', 'Spirituelle Weisheit', JSON_OBJECT('summary', 'Spirituelle Weisheit lädt dazu ein, oberflächliche Ablenkungen loszulassen und die stille Achtsamkeit in jedem Atemzug wahrzunehmen. Durch Selbstreflexion, Mitgefühl und regelmässige Praxis wird innere Ruhe erlebbar.'), 'published', 0),

