UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'தொடக்கநிலை மற்றும் அனுபவமுள்ள பயிற்சியாளர்களுக்காக வடிவமைக்கப்பட்ட தியானம் மற்றும் ஓம் அமர்வுகள், மன அழுத்தத்தைத் தணித்து, கவனத்தை ஆழப்படுத்தி, உள்ளார்ந்த தெளிவை வளர்க்க உதவும்.', '$.duration', '60 நிமிடங்கள்', '$.mode', 'நேரடி மற்றும் இணையவழி')
WHERE content_type = 'services' AND slug = 'meditation-aum' AND locale = 'ta' AND JSON_EXTRACT(payload_json, '$.fullDesc') IS NULL;
UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'உடல் சீரமைப்பு, மூச்சுக் கட்டுப்பாடு மற்றும் விழிப்புணர்வான தளர்வை இணைக்கும் மென்மையான முதல் இடைநிலை யோகப் பயிற்சிகள், ஆற்றலையும் நெகிழ்வுத்தன்மையையும் மீட்டெடுக்க உதவும்.', '$.duration', '75 நிமிடங்கள்', '$.mode', 'குழு மற்றும் தனிப்பட்ட அமர்வுகள்')
WHERE content_type = 'services' AND slug = 'yoga-wellness' AND locale = 'ta' AND JSON_EXTRACT(payload_json, '$.fullDesc') IS NULL;
UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'சுயவிசாரணை, உணர்ச்சி சமநிலை மற்றும் காலத்தால் அழியாத ஞானத்தை நவீன வாழ்வில் பயன்படுத்துதல் ஆகியவற்றை மையமாகக் கொண்ட தனிநபர் மற்றும் சிறு குழு ஆன்மீக வழிகாட்டுதல்.', '$.duration', '45 நிமிடங்கள்', '$.mode', 'தனிப்பட்ட ஆலோசனை')
WHERE content_type = 'services' AND slug = 'spiritual-guidance' AND locale = 'ta' AND JSON_EXTRACT(payload_json, '$.fullDesc') IS NULL;
UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'உள்ளார்ந்த விழிப்புணர்வை அடிப்படையாகக் கொண்டு சுயஒழுக்கம், தொடர்பாடல் மற்றும் மகிழ்ச்சியான இலக்கு அமைத்தலை வலுப்படுத்தும் நடைமுறை ஆளுமை வளர்ச்சி வழிகாட்டுதல்.', '$.duration', '60 நிமிடங்கள்', '$.mode', 'பட்டறை மற்றும் தனிநபர் அமர்வு')
