UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'பக்திப் பண்கள், ஒலியதிர்வு மற்றும் அமைதியையும் ஒருமுகப்படுத்தலையும் ஊக்குவிக்கும் இசை வெளிப்பாடுகளை ஆராயும் உள்ளம் தொடும் அசல் சங்கீத அமர்வுகள்.', '$.duration', '60 நிமிடங்கள்', '$.mode', 'நேரலை மற்றும் வழிகாட்டப்பட்ட அமர்வுகள்')
