UPDATE cms_content SET payload_json = JSON_SET(payload_json, '$.fullDesc', 'தியானம், தமிழ் பண்பாட்டு மரபு மற்றும் முழுமையான நல்வாழ்வு ஆகியவற்றை உள்ளடக்கிய பல அமர்வுப் பட்டறைகள் மற்றும் சமூகக் கற்றல் நிகழ்ச்சிகள்.', '$.duration', 'அரை நாள் / பல வாரங்கள்', '$.mode', 'சமூக மற்றும் இணையவழி')
